<?php
require_once __DIR__.'/answer_preview.php';

function final_review_interviews(PDO $pdo,int $answerId): array {
 $st=$pdo->prepare('SELECT s.*,ic.id assignment_id,ic.candidate_id FROM interview_candidate ic JOIN interview_session s ON s.id=ic.session_id WHERE ic.answer_id=? ORDER BY s.interview_date DESC,s.id DESC');
 $st->execute([$answerId]);$sessions=$st->fetchAll(PDO::FETCH_ASSOC);
 foreach($sessions as &$session){
  $st=$pdo->prepare('SELECT si.id interviewer_assignment_id,si.weight,si.is_lead,u.real_name,sc.id score_id,sc.detail_json,COALESCE(sc.total_score,(sc.suzhi_score+sc.postq_score)/40.0) normalized_score,sc.strengths,sc.risks,sc.development,sc.recommendation,sc.salary_range,sc.available_date,sc.comment,sc.submitted_at FROM session_interviewer si JOIN user u ON u.id=si.user_id LEFT JOIN interview_score sc ON sc.interviewer_id=si.id AND sc.interview_candidate_id=? WHERE si.session_id=? ORDER BY si.is_lead DESC,si.id');
  $st->execute([$session['assignment_id'],$session['id']]);$session['reviewers']=$st->fetchAll(PDO::FETCH_ASSOC);
  $weighted=0;$weights=0;$submitted=0;
  foreach($session['reviewers'] as $r){if($r['score_id']===null)continue;$submitted++;if($r['normalized_score']!==null&&$r['weight']>0){$weighted+=(float)$r['normalized_score']*20*(float)$r['weight'];$weights+=(float)$r['weight'];}}
  $session['submitted']=$submitted;$session['average']=$weights>0?round($weighted/$weights,2):null;
  $st=$pdo->prepare("SELECT responses,submitted_at FROM interview_feedback WHERE session_id=? AND candidate_id=? AND COALESCE(responses,'') NOT IN ('','{}') ORDER BY submitted_at DESC");
  $st->execute([$session['id'],$session['candidate_id']]);$session['questionnaires']=$st->fetchAll(PDO::FETCH_ASSOC);
 }unset($session);return $sessions;
}
function render_final_review(PDO $pdo,?array $selected,array $rows,array $history,string $keyword,int $filterPost): void {
 if(!$selected){echo '<div class="panel empty-state"><b>暂无待终审人员</b></div>';return;}
 $report=($_GET['view']??'')==='report';
 $context=['page'=>'talent','tab'=>'final','id'=>$selected['id'],'q'=>$keyword,'post_id'=>$filterPost];
 $detail=assessment_answer_detail($pdo,(int)$selected['answer_id']);$sessions=final_review_interviews($pdo,(int)$selected['answer_id']);
 $latest=null;foreach($sessions as $session)if($session['status']!=='canceled'){$latest=$session;break;}
 $questionnaireCount=array_sum(array_map(fn($s)=>count($s['questionnaires']),$sessions));
 $recommendations=['strong'=>'强烈推荐录用','recommend'=>'推荐录用','pending'=>'待定 / 需要复试','reject'=>'不推荐录用'];
 $dimensions=['professional'=>['专业知识与技能','30%'],'experience'=>['工作经验与业绩','25%'],'communication'=>['沟通表达能力','15%'],'logic'=>['逻辑思维与分析','10%'],'teamwork'=>['团队协作能力','10%'],'learning'=>['学习与适应能力','5%'],'professionalism'=>['仪表举止与职业素养','5%']];
 ?>
 <?php if(!$report):?><div class="final-review-workspace" data-final-review-workspace><aside class="panel final-review-queue"><header><h2>待终审</h2><span><?=count($rows)?> 人</span></header><nav aria-label="待终审候选人"><?php foreach($rows as $row):?><a class="final-review-person <?=$row['id']===$selected['id']?'active':''?>" <?=$row['id']===$selected['id']?'aria-current="true"':''?> href="?<?=e(http_build_query(array_merge($context,['id'=>$row['id']])))?>"><div><b><?=e($row['name'])?></b><small><?=e($row['post_name'])?></small></div><strong><?=number_format((float)$row['total_score'],1)?></strong></a><?php endforeach;?></nav></aside><div class="final-review-main"><?php endif;?>
 <div class="final-report-tools">
 <?php if($report):?><a class="btn secondary" href="?<?=e(http_build_query($context))?>">返回审核主页</a><form method="get"><input type="hidden" name="page" value="talent"><input type="hidden" name="tab" value="final"><input type="hidden" name="view" value="report"><input type="hidden" name="q" value="<?=e($keyword)?>"><input type="hidden" name="post_id" value="<?=$filterPost?>"><label for="final-candidate">待终审人员（<?=count($rows)?>）</label><select id="final-candidate" name="id" onchange="this.form.requestSubmit()"><?php foreach($rows as $row):?><option value="<?=$row['id']?>" <?=$row['id']===$selected['id']?'selected':''?>><?=e($row['name'].' · '.$row['post_name'])?></option><?php endforeach;?></select><noscript><button>查看</button></noscript></form><button type="button" class="btn secondary" onclick="window.print()">打印评审报告</button>
 <?php else:?><span>审核工作台</span><a class="btn secondary" target="_blank" rel="noopener" href="?<?=e(http_build_query(array_merge($context,['view'=>'report'])))?>">查看完整报告 / 打印</a><?php endif;?></div>
 <article class="panel final-report <?=$report?'':'final-review-tabbed'?>" id="final-review-report">
 <header class="final-report-profile"><div><small>人才审核 / <?=$report?'完整评审报告':'审核工作台'?></small><h2><?=e($selected['name'])?></h2><p><?=e($selected['post_name'])?></p><p><?=e($selected['mobile'].' · '.$selected['edu'].((float)($selected['work_years']??0)>0?' · '.$selected['work_years'].' 年经验':''))?></p></div><span class="status-badge">待终审</span></header>
 <div class="final-report-metrics"><div><small>测评总分</small><b><?=number_format((float)$selected['total_score'],1)?> <em>/ 100</em></b><p>基本条件 <?=number_format((float)$selected['eval_score'],1)?> · 素质 <?=number_format((float)$selected['suzhi_score'],1)?> · 专业 <?=number_format((float)$selected['postq_score'],1)?></p></div><div><small>最近有效场次面试分</small><b><?=$latest&&$latest['average']!==null?number_format($latest['average'],2):'—'?> <em>/ 100</em></b><p><?=$latest?'评分已提交 '.$latest['submitted'].' / '.count($latest['reviewers']):'暂无面试记录'?><?php if($latest&&$latest['submitted']<count($latest['reviewers'])):?> · 当前为已提交评分汇总<?php endif;?></p></div><div><small>调查问卷</small><b><?=$questionnaireCount?'已提交':'未提交'?></b><p>按面试场次展示原始回答</p></div><div><small>面试进度</small><b><?=!empty($selected['interview_done'])?'已完成':'待完成'?></b><p>各场次评分明细见下方</p></div></div>
 <nav class="final-report-nav" aria-label="<?=$report?'评审报告目录':'审核资料分类'?>"><?php if(!$report):?><a href="#final-overview">总览</a><?php endif;?><a href="#final-assessment">01 测评答题</a><a href="#final-questionnaire">02 调查问卷</a><a href="#final-interviews">03 面试评价</a><a href="#final-history">04 审核记录</a><a href="#final-decision">终审意见</a></nav>
 <div class="final-report-content">
 <?php if(!$report):?><section id="final-overview" class="final-report-section"><h2>终审资料概览</h2><div class="final-overview-grid"><div class="final-overview-card"><h3>资料完整度</h3><dl><dt>测评答题与附录</dt><dd><?=$detail?'已读取本次答卷':'暂无记录'?></dd><dt>调查问卷</dt><dd><?=$questionnaireCount?'已提交':'未提交'?></dd><dt>最近场次评分</dt><dd><?=$latest?$latest['submitted'].' / '.count($latest['reviewers']).' 已提交':'暂无面试记录'?></dd><dt>面试进度</dt><dd><?=!empty($selected['interview_done'])?'已完成':'待完成'?></dd></dl></div><div class="final-overview-card"><h3>最近场次面试官建议</h3><?php if(!$latest||!$latest['reviewers']):?><p class="final-report-note">暂无面试评价。</p><?php else:foreach($latest['reviewers'] as $r):?><div class="final-overview-recommendation"><b><?=e($r['real_name'])?></b><span><?=$r['score_id']===null?'未提交':e($recommendations[$r['recommendation']]??'历史评分')?></span><small><?=$r['score_id']!==null&&$r['normalized_score']!==null?number_format((float)$r['normalized_score']*20,2).' / 100':'—'?></small></div><?php endforeach;endif;?></div></div><h3 class="final-overview-title">面试官原始评价</h3><?php if(!$latest):?><p class="final-report-note">暂无面试记录。</p><?php else:foreach($latest['reviewers'] as $r):if($r['score_id']===null)continue;?><article class="final-reviewer"><header><h4><?=e($r['real_name'])?></h4><span><?=e($recommendations[$r['recommendation']]??'历史评分')?></span></header><dl><dt>优势与亮点</dt><dd><?=nl2br(e($r['strengths']?:($r['comment']?:'未填写')))?></dd><dt>不足与风险</dt><dd><?=nl2br(e($r['risks']?:'未填写'))?></dd></dl></article><?php endforeach;endif;?></section><?php endif;?>
 <section id="final-assessment" class="final-report-section"><h2><small>01</small>测评题目与作答</h2><p class="final-report-note">展示本次测评提交时的题目和回答，包含基本信息、基本条件、追问、基本素质、专业题目与附录。</p><?php if($detail):render_assessment_answer_sections($detail);if($detail['conditions']):?><h3>基本条件评分记录</h3><div class="final-score-scroll"><table class="final-score-table"><thead><tr><th>评分项目</th><th>匹配条件</th><th>记录得分</th></tr></thead><tbody><?php foreach($detail['conditions'] as $condition):?><tr><td><?=e($condition['dim_name'])?></td><td><?=e($condition['matched_tier']??'未记录')?></td><td><?=number_format((float)$condition['score'],2)?></td></tr><?php endforeach;?></tbody></table></div><p class="final-report-note">以上为各项评分记录；基本条件折算后的总分见报告顶部。</p><?php endif;else:?><p>本次测评记录不存在。</p><?php endif;?></section>
 <section id="final-questionnaire" class="final-report-section"><h2><small>02</small>调查问卷原答</h2><?php if(!$questionnaireCount):?><p class="final-report-note">尚未提交调查问卷。</p><?php endif;foreach($sessions as $session):foreach($session['questionnaires'] as $questionnaire):$responses=json_decode($questionnaire['responses'],true)?:[];?>
 <div class="final-session-heading"><h3><?=e($session['interview_date'].' '.$session['time_range'])?> · 场次 #<?=$session['id']?></h3><p>提交时间：<?=e($questionnaire['submitted_at'])?><?= $session['status']==='canceled'?' · 已取消场次的历史问卷':''?></p></div>
 <?php if(empty($responses['questions'])):?><p class="final-report-note">历史问卷未保存题目快照。</p><?php endif;foreach(($responses['questions']??[]) as $i=>$question):render_assessment_answer_item(($i+1).'．'.assessment_answer_text($question),$responses['answers'][$i]??'');endforeach;endforeach;endforeach;?></section>
 <section id="final-interviews" class="final-report-section"><h2><small>03</small>面试官详细评价</h2><p class="final-report-note">测评分与面试分分别展示。面试维度按固定权重汇总，再按面试官权重计算场次得分；未提交评分不按零分计入。</p><?php if(!$sessions):?><p>暂无面试记录。</p><?php endif;foreach($sessions as $session):?>
 <div class="final-interview-session"><div class="final-session-heading"><h3><?=e($session['interview_date'].' '.$session['time_range'])?> · 场次 #<?=$session['id']?></h3><p><?=e($session['location'])?> · <?=e(['pending'=>'待开始','scoring'=>'评分中','done'=>'已结束','canceled'=>'已取消'][$session['status']]??$session['status'])?> · 已提交 <?=$session['submitted']?> / <?=count($session['reviewers'])?> · 场次加权得分 <?=$session['average']===null?'—':number_format($session['average'],2).' / 100'?></p></div>
 <?php if(!$session['reviewers']):?><p class="final-report-note">本场暂无面试官配置。</p><?php else:?><div class="final-score-scroll"><table class="final-score-table"><thead><tr><th>评分维度</th><th>维度权重</th><?php foreach($session['reviewers'] as $r):?><th><?=e($r['real_name'])?><small>权重 <?=e($r['weight'])?><?=$r['is_lead']?' · 主面试官':''?></small></th><?php endforeach;?></tr></thead><tbody><?php foreach($dimensions as $code=>[$label,$weight]):?><tr><td><?=$label?></td><td><?=$weight?></td><?php foreach($session['reviewers'] as $r):$dims=json_decode($r['detail_json']??'{}',true)?:[];?><td><?=$r['score_id']===null?'未提交':(isset($dims[$code])?e((string)((float)$dims[$code]*20)):'未记录')?></td><?php endforeach;?></tr><?php endforeach;?><tr><th>加权总分 / 100</th><td>100%</td><?php foreach($session['reviewers'] as $r):?><td><strong><?=$r['score_id']===null?'未提交':($r['normalized_score']===null?'未记录':number_format((float)$r['normalized_score']*20,2))?></strong></td><?php endforeach;?></tr></tbody></table></div>
 <?php foreach($session['reviewers'] as $r):?><article class="final-reviewer"><header><h4><?=e($r['real_name'])?></h4><span><?= $r['score_id']===null?'未提交评分':e($recommendations[$r['recommendation']]??'历史评分')?></span></header><?php if($r['score_id']!==null):?><p class="final-report-note">提交时间：<?=e($r['submitted_at'])?></p><?php foreach(['strengths'=>'优势与亮点','risks'=>'不足与风险','development'=>'发展建议','salary_range'=>'建议薪资范围','available_date'=>'预计到岗日期','comment'=>'其他评价 / 历史评语'] as $field=>$label):if($field==='comment'&&(!$r[$field]||$r[$field]===$r['strengths']))continue;?><dl><dt><?=$label?></dt><dd><?=nl2br(e($r[$field]?:'未填写'))?></dd></dl><?php endforeach;else:?><p class="final-report-note">该面试官尚未提交本场评分。</p><?php endif;?></article><?php endforeach;endif;?></div><?php endforeach;?></section>
 <section id="final-history" class="final-report-section"><h2><small>04</small>审核记录</h2><?php if(!$history):?><p class="final-report-note">暂无审核记录。</p><?php endif;foreach($history as $h):?><article class="final-reviewer"><header><h4><?=e($h['real_name'])?> · <?=e(review_label($h['stage']))?></h4><span><?=e(review_label($h['opinion']))?></span></header><p><?=nl2br(e($h['note']?:'未填写意见'))?></p><small><?=e($h['created_at'])?></small></article><?php endforeach;?></section>
 </div>
 <section class="final-decision" id="final-decision"><h3>终审意见</h3><?php if(empty($selected['interview_done'])):?><p>等待面试完成后，即可提交终审结论。</p><?php else:?><form class="review-form" method="post" action="?page=talent&amp;action=review"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="result_id" value="<?=$selected['id']?>"><input type="hidden" name="stage" value="final"><input type="hidden" name="current" value="interview"><label for="final-note">结合测评、调查问卷及面试评价填写终审意见</label><textarea id="final-note" name="note" placeholder="填写终审意见" rows="3"></textarea><div><button name="op" value="reject" class="btn danger">终审不录用</button><button name="op" value="pass" class="btn primary" onclick="return confirm('确认终审录用？系统将更新该人才的录用状态。')">✓ 确认录用</button></div></form><?php endif;?></section>
